<script setup lang="ts">
import { computed, ref } from 'vue'
import { installLink, useInstallApp, type InstallHelp } from '@/composables/useInstallApp'
const emit=defineEmits<{close:[]}>()
const {help,canPrompt,promptInstall}=useInstallApp();const link=installLink();const copied=ref(false)
const SHARE='nút <b>Chia sẻ</b> (ô vuông có mũi tên ⬆️)'
const PUSH_NOTE='Trên iPhone (iOS 16.4 trở lên), chỉ app mở từ <b>màn hình chính</b> mới nhận được thông báo nhắc việc.'
// Steps for the browsers that have no install dialog of their own (or where it was already dismissed)
const GUIDE:Record<InstallHelp,{steps:string[];note?:string;copy?:boolean}>={
  'in-app':{steps:['Bấm <b>⋯</b> ở góc trên bên phải.','Chọn <b>Mở bằng trình duyệt</b>: iPhone là <b>Safari</b>, Android là <b>Chrome</b>.','Trên trình duyệt đó, bấm lại <b>📲 Cài app vào điện thoại</b>.'],note:'Zalo, Facebook mở link bằng trình duyệt riêng nên không cài được app. Không thấy mục mở bằng trình duyệt thì sao chép link bên dưới rồi dán vào Safari hoặc Chrome.',copy:true},
  'ios-safari':{steps:[`Bấm ${SHARE}. Không thấy nút này thì bấm <b>⋯</b> trước.`,'Kéo xuống, chọn <b>Thêm vào MH chính</b> rồi bấm <b>Thêm</b>.','Mở app từ biểu tượng <b>TNTT Lịch</b> trên màn hình chính.'],note:PUSH_NOTE},
  'ios-other':{steps:[`Bấm ${SHARE} ở thanh địa chỉ hoặc trong menu <b>⋯</b>.`,'Chọn <b>Thêm vào MH chính</b> rồi bấm <b>Thêm</b>.','Không thấy mục này? Sao chép link bên dưới, mở bằng <b>Safari</b> rồi làm lại.'],note:PUSH_NOTE,copy:true},
  android:{steps:['Bấm <b>⋮</b> ở góc trên bên phải Chrome.','Chọn <b>Cài đặt ứng dụng</b> (hoặc <b>Thêm vào màn hình chính</b>).','Bấm <b>Cài đặt</b>: biểu tượng <b>TNTT Lịch</b> sẽ có trên màn hình chính.'],note:'Samsung Internet: bấm <b>☰</b> → <b>Thêm trang vào</b> → <b>Màn hình chính</b>.'},
  desktop:{steps:['Bấm biểu tượng <b>Cài đặt ứng dụng</b> ở cuối thanh địa chỉ Chrome hoặc Edge.','Không thấy thì mở menu <b>⋮</b> / <b>⋯</b> → chọn mục <b>Cài đặt</b> TNTT Lịch.','Bấm <b>Cài đặt</b>: app mở trong cửa sổ riêng.']},
}
const guide=computed(()=>GUIDE[help.value])
// Opened from the QR code there was no tap yet to start the browser's own dialog; this button is that tap
async function installNow(){await promptInstall();emit('close')}
async function copy(){try{await navigator.clipboard.writeText(link);copied.value=true;setTimeout(()=>copied.value=false,2000)}catch{/* the link stays on screen to copy by hand */}}
</script>
<template><Teleport to="body"><div class="overlay sheet-overlay" @click.self="emit('close')"><section class="sheet"><div class="handle"></div><h3>📲 Cài app TNTT Lịch</h3><p class="lead">Cài vào màn hình chính để mở nhanh như app thật, toàn màn hình và nhận thông báo nhắc việc.</p><template v-if="canPrompt"><button class="now" @click="installNow">📲 Cài ngay</button><p class="or">Hoặc tự cài theo các bước:</p></template><ol class="steps"><li v-for="(s,i) in guide.steps" :key="i"><span class="no">{{i+1}}</span><span v-html="s"></span></li></ol><p v-if="guide.note" class="note" v-html="guide.note"></p><div v-if="guide.copy" class="link"><span>{{link}}</span><button @click="copy">{{copied?'✓ Đã chép':'📋 Sao chép'}}</button></div><button class="done" @click="emit('close')">Đã hiểu</button></section></div></Teleport></template>
<style scoped>.sheet{background:#fff;width:100%;max-width:560px;margin:0 auto;max-height:100%;display:flex;flex-direction:column;gap:11px;overflow-y:auto;border-radius:24px 24px 0 0;padding:12px 18px calc(20px + env(safe-area-inset-bottom));box-shadow:0 -10px 30px rgba(15,23,42,.18)}.sheet>*{flex:none}.handle{width:42px;height:5px;border-radius:5px;background:#cbd5e1;margin:0 auto}h3{margin:0;font-size:1.08rem}.lead{margin:0;font-size:.84rem;color:#64748b;line-height:1.45}.steps{list-style:none;margin:0;padding:0;display:grid;gap:8px}.steps li{display:flex;align-items:flex-start;gap:10px;background:#f8fafc;border-radius:14px;padding:10px 12px;font-size:.88rem;line-height:1.45;overflow-wrap:anywhere}.no{flex:none;width:24px;height:24px;border-radius:50%;background:#1d4ed8;color:#fff;display:grid;place-items:center;font-size:.78rem;font-weight:900}.note{margin:0;background:#fff7ed;border:1px solid #fed7aa;color:#9a3412;border-radius:13px;padding:9px 11px;font-size:.8rem;line-height:1.45}.link{display:flex;align-items:center;gap:8px;border:1px dashed #cbd5e1;border-radius:13px;padding:7px 7px 7px 12px}.link span{flex:1;min-width:0;font-size:.8rem;color:#334155;overflow-wrap:anywhere;user-select:all}.link button{flex:none;border:0;border-radius:999px;padding:7px 12px;background:#eef2ff;color:#3730a3;font-weight:800;font-size:.78rem}.done{border:0;border-radius:14px;padding:13px;background:#1d4ed8;color:#fff;font-weight:800}.now{border:0;border-radius:14px;padding:14px;background:#16a34a;color:#fff;font-weight:900;font-size:1rem;box-shadow:0 8px 20px rgba(22,163,74,.25)}.or{margin:0;font-size:.78rem;font-weight:800;color:#64748b}</style>
